// Einmalig 2026-08-23: Nachtraeglicher Matrix-Versand fuer 4 Kernbotschaft-Umfragen
// (Headline-Auswahl), die waehrend/um den 5-taegigen Matrix-Ausfall (a9c53a3) haengen
// geblieben sind - headlineChoiceStage='awaiting_headline_choice' seit Tagen ohne
// Reaktionsmoeglichkeit, da die Umfrage nie ankam. Nachrichtentext 1:1 nach der Logik
// von 'Satire-Ergebnis: Baue Text-Auswahl + Umfrage' in ALLRIS_P3e_Kernbotschaft
// nachgebaut (satireAgentJson/faktenAgentJson sind bereits vollstaendig in der DB
// vorhanden, keine neue KI-Anfrage noetig). Die optionale Lern-Agent-Einschaetzung
// (rein informativ) wird bewusst weggelassen.
//
// 2 weitere aeltere haengende Umfragen (2026/030, 2026/003, beide von Ende Juli, lange
// vor dem Ausfall) bewusst NICHT enthalten - unabhaengiges, separates Thema.
const TARGET_KEYS = ["vol_10821","vol_10845","vol_10838","vol_10801"];

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseObj(v) {
  if (!v) return {};
  if (typeof v === 'object' && !Array.isArray(v)) return v;
  try { const p = JSON.parse(String(v)); return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {}; }
  catch (e) { return {}; }
}
function asArr(v) {
  if (Array.isArray(v)) return v.filter(Boolean).map(safeStr);
  if (typeof v === 'string' && v.trim()) { try { const p = JSON.parse(v); if (Array.isArray(p)) return p.filter(Boolean).map(safeStr); } catch (e) {} }
  return [];
}
function normalizeGrounding(v) {
  return safeStr(v).toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function groundingTokens(v) { return normalizeGrounding(v).split(' ').filter(t => t.length >= 4); }
function candidateContainsTerm(text, term) {
  const nt = normalizeGrounding(text), nq = normalizeGrounding(term);
  if (!nt || !nq) return false;
  if (nt.includes(nq)) return true;
  const tt = groundingTokens(text), qt = groundingTokens(term);
  return qt.some(q => tt.some(t => t.includes(q) || q.includes(t)));
}
function groundingHint(candidateText, groundingTerms) {
  if (!groundingTerms.length) return '';
  const hit = groundingTerms.find(t => candidateContainsTerm(candidateText, t));
  return hit ? ('✓ nah an den Fakten (' + hit + ')') : '⚠️ wenig Bezug zu den Fakten – bitte prüfen';
}

const rows = $input.all().map(i => i.json).filter(r => TARGET_KEYS.includes(r.vorgangKey));
console.log('[Headline-Nachtrag] ' + rows.length + ' von ' + TARGET_KEYS.length + ' Ziel-Zeilen gefunden.');

return rows.map(row => {
  const satire = parseObj(row.satireAgentJson);
  const variants = Array.isArray(satire.variants) ? satire.variants : [];
  const kernbotschaft = safeStr(satire.kernbotschaft);
  const fakten = parseObj(row.faktenAgentJson);
  const groundingTerms = [...asArr(fakten.requiredTerms), ...asArr(fakten.concreteNumbers), ...asArr(fakten.requiredObjects)].filter(Boolean);
  const vorgangKey = safeStr(row.vorgangKey);
  const vorgangsnummer = safeStr(row.vorgangsnummer);
  const title = safeStr(row.title);
  const vnCode = vorgangsnummer.replace(/[^0-9A-Za-z]+/g, '-').replace(/^-+|-+$/g, '');

  const candidates = variants.slice(0, 5).map((v, i) => {
    const imageHeadline = safeStr(v.imageHeadline);
    const imageSubline = safeStr(v.imageSubline);
    const satireBrief = safeStr(v.satireBrief);
    return {
      code: (vnCode ? vnCode + '-' : '') + 'K' + (i + 1),
      imageHeadline, imageSubline, satireBrief,
      groundingHintText: groundingHint(imageHeadline + ' ' + imageSubline + ' ' + satireBrief, groundingTerms)
    };
  }).filter(c => c.imageHeadline && c.imageSubline);

  if (candidates.length < 2 || !kernbotschaft) {
    console.warn('[Headline-Nachtrag] ' + vorgangKey + ': zu wenige gueltige Kandidaten oder keine kernbotschaft, uebersprungen.');
    return null;
  }

  const lines = ['🎯 Kernbotschaft für ' + vorgangsnummer + ' – ' + title + ' (nachtraeglich gesendet, Matrix-Ausfall 18.-23.08.)', '', kernbotschaft, '', '🎨 Formulierungen zur Auswahl:', ''];
  for (const c of candidates) {
    lines.push(c.code + ': ' + c.imageHeadline + ' – ' + c.imageSubline);
    if (c.satireBrief) lines.push('   ' + c.satireBrief);
    if (c.groundingHintText) lines.push('   ' + c.groundingHintText);
  }
  lines.push('');
  const exampleCode = candidates[0].code;
  lines.push('Antworte mit dem gewünschten Code (z.B. "' + exampleCode + '"), um Text UND Bild freizugeben, oder mit "' + vnCode + '-X" für eine komplett neue Kernbotschaft. Vor deiner Antwort wird noch nichts veröffentlicht.');
  const matrixMessage = lines.join('\n');
  const txnId = 'satire_hdl_catchup_' + Date.now() + '_' + vorgangKey.replace(/[^a-zA-Z0-9]/g, '').substring(0, 10);

  return { json: { vorgangKey, vorgangsnummer, matrixMessage, txnId } };
}).filter(Boolean);
